INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT138-S2-Q3$batch04$, 138, 2, 3, $batch04$Paradox$batch04$, $batch04$Scientist: Venus contains a hot molten core, like that of Earth. Also like Earth, Venus must expel the excess heat the core generates. On Earth, this occurs entirely through active volcanos and fissures created when tectonic plates separate. Yet Venus has neither active volcanos nor fissures caused by the movement of tectonic plates.$batch04$, $batch04$Which one of the following, if true, does the most to resolve the apparent discrepancy described by the scientist?$batch04$, $batch04$B$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=138 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Rock on the surface of Venus remains solid at much higher temperatures than does rock on Earth.$batch04$, $batch04$Half Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$The surface of Venus is relatively thin, allowing internally produced heat to radiate into space.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$The interior of Venus undergoes greater fluctuations in temperature than does that of Earth.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Though Venus lacks active volcanoes and heat-diffusing fissures, it has surface movement somewhat like that of Earth.$batch04$, $batch04$Unclear Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$The atmosphere of Venus is significantly hotter than that of Earth.$batch04$, $batch04$Deepens Paradox$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Venus has a hot core and must expel its excess heat, as Earth does. Earth does it entirely through volcanos and fissures.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Venus has no active volcanos and no fissures from moving plates?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$Earth's method is not the only possible one. If Venus has another way to release heat, the puzzle goes away.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find another way for Venus to get rid of its heat.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Rock staying solid at high temperatures might explain why Venus has no volcanos. It does not explain where the heat goes.$batch04$), ($batch04$B$batch04$, $batch04$Venus's surface is thin, so heat from inside radiates straight into space. That is a way out for the heat without volcanos or fissures.$batch04$), ($batch04$C$batch04$, $batch04$Bigger temperature swings inside Venus do not explain how it releases heat.$batch04$), ($batch04$D$batch04$, $batch04$Surface movement "somewhat like" Earth's is not a way of releasing heat, and the stimulus already says Venus has no fissures from that movement.$batch04$), ($batch04$E$batch04$, $batch04$A hotter atmosphere would make it harder, not easier, for heat to escape.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT138-S2-Q3$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
